function policyCase(
  id: string,
  category: string,
  ruleId: string,
  module: string,
  input: PolicyEvaluationCase["input"],
  expected: Record<string, unknown>,
  source: SourceKey,
  derivation: string,
  options: { paramsOverride?: Record<string, unknown>; asOfDate?: string } = {},
): PolicyEvaluationCase {
  return {
    id,
    category,
    ruleId,
    module,
    input,
    expected,
    evidence: { ...SOURCES[source], derivation },
    ...options,
  };
}

